(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-3-endocrine-quiz-version-5"]={"title":"Endocrine System — Anatomy Exam 3 (Set 5)","category":"Anatomy","exam":"Exam 3","sem":"summer-1-2026","questions":[{"q":"Which structure is considered a primary endocrine organ?","choices":["Liver","Small intestine","Pituitary gland","Stomach"],"answer":2,"exp":"The pituitary is a primary endocrine organ. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"Which organ has endocrine functions but is not primarily classified as an endocrine gland?","choices":["Pituitary gland","Heart","Thyroid gland","Parathyroid gland"],"answer":1,"exp":"The heart has endocrine functions but is not primarily an endocrine gland. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"Which hormone is produced by adipose tissue?","choices":["Leptin","Calcitonin","Oxytocin","Aldosterone"],"answer":0,"exp":"Adipose tissue produces leptin. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"The kidney performs an endocrine function by producing","choices":["prolactin and growth hormone","calcitriol and erythropoietin","insulin and glucagon","cortisol and aldosterone"],"answer":1,"exp":"The kidney produces erythropoietin and calcitriol. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"The endocrine system differs from an exocrine system because endocrine glands","choices":["secrete only steroid hormones","contain only nervous tissue","release hormones into the bloodstream","release products through ducts"],"answer":2,"exp":"Endocrine glands release hormones into blood rather than through ducts. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"Which organ produces atrial natriuretic peptide?","choices":["Thyroid gland","Adrenal gland","Kidney","Heart"],"answer":3,"exp":"The heart produces ANP. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"Which organ produces melatonin?","choices":["Thymus","Pancreas","Pineal gland","Pituitary gland"],"answer":2,"exp":"The pineal gland produces melatonin. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"Which structure produces thymosins?","choices":["Hypothalamus","Thyroid","Adrenal cortex","Thymus"],"answer":3,"exp":"The thymus produces thymosins. — Anatomy Exam 3 — I — General Endocrine Anatomy"},{"q":"The pituitary gland is also called the","choices":["thymus","neurocranium","epiphysis","hypophysis"],"answer":3,"exp":"Pituitary gland = hypophysis. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The pituitary gland is attached to the hypothalamus by the","choices":["fornix","optic tract","infundibulum","corpus callosum"],"answer":2,"exp":"The infundibulum connects the pituitary to the hypothalamus. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The pituitary gland lies within the","choices":["foramen magnum","cribriform plate","hypophyseal fossa","jugular foramen"],"answer":2,"exp":"The pituitary occupies the hypophyseal fossa. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The hypophyseal fossa is located within the","choices":["ethmoid bone","temporal bone","sphenoid bone","occipital bone"],"answer":2,"exp":"The sella turcica is part of the sphenoid bone. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which structure lies directly superior to the pituitary gland?","choices":["Optic chiasm","Dorsum sellae","Sphenoid sinus","Nasopharynx"],"answer":0,"exp":"The optic chiasm lies superior to the pituitary. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which structure lies inferior and anterior to the pituitary gland?","choices":["Sphenoid sinus","Third ventricle","Cavernous sinus","Optic tract"],"answer":0,"exp":"The sphenoid sinus lies inferior and anterior to the pituitary. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The pituitary gland is related laterally to the","choices":["cavernous sinuses","sagittal sinuses","transverse sinuses","sigmoid sinuses"],"answer":0,"exp":"The cavernous sinuses lie lateral to the pituitary. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The structure located posterior to the pituitary gland is the","choices":["dorsum sellae","clivus only","optic chiasm","crista galli"],"answer":0,"exp":"The dorsum sellae lies posterior to the gland. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The dural structure covering the superior aspect of the pituitary is the","choices":["diaphragma sellae","tentorium cerebelli","falx cerebelli","falx cerebri"],"answer":0,"exp":"The diaphragma sellae covers the gland superiorly. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The diaphragma sellae is pierced by the","choices":["internal carotid artery","optic nerve","oculomotor nerve","infundibulum"],"answer":3,"exp":"The infundibulum pierces the diaphragma sellae. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"A pituitary mass growing superiorly is most likely to compress the","choices":["vagus nerve","optic chiasm","facial nerve","olfactory bulb"],"answer":1,"exp":"Superior growth may compress the optic chiasm. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Compression of the optic chiasm by a pituitary tumor classically produces","choices":["bitemporal hemianopia","left homonymous hemianopia","monocular blindness","central scotoma only"],"answer":0,"exp":"Optic chiasm compression causes bitemporal hemianopia. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"A pituitary mass extending laterally may involve the","choices":["frontal sinus","superior sagittal sinus","straight sinus","cavernous sinus"],"answer":3,"exp":"Lateral extension may enter the cavernous sinus. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which structure is part of the adenohypophysis?","choices":["Infundibulum","Pars nervosa","Pars distalis","Hypothalamo-hypophyseal tract"],"answer":2,"exp":"Pars distalis belongs to the adenohypophysis. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which structure is part of the neurohypophysis?","choices":["Pars nervosa","Pars distalis","Pars intermedia","Pars tuberalis"],"answer":0,"exp":"Pars nervosa belongs to the neurohypophysis. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The adenohypophysis includes all of the following except","choices":["pars nervosa","pars intermedia","pars distalis","pars tuberalis"],"answer":0,"exp":"Pars nervosa is not part of the adenohypophysis. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The posterior pituitary is connected to the hypothalamus by the","choices":["mammillothalamic tract","fornix","optic radiation","infundibulum"],"answer":3,"exp":"The posterior lobe connects through the infundibulum. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which hormones are synthesized in the hypothalamus and released from the posterior pituitary?","choices":["TSH and ACTH","ADH and oxytocin","GH and prolactin","FSH and LH"],"answer":1,"exp":"ADH and oxytocin are made in the hypothalamus and released posteriorly. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The anterior pituitary receives blood mainly through the","choices":["superior sagittal sinus","hypophyseal portal system","cerebral aqueduct","systemic venous system only"],"answer":1,"exp":"The anterior pituitary receives portal blood. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The posterior pituitary receives primarily","choices":["direct arterial blood","portal venous blood","lymphatic blood","blood from the internal jugular vein"],"answer":0,"exp":"The posterior pituitary receives direct arterial blood. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The primary capillary plexus of the hypophyseal portal system is associated with the","choices":["pars nervosa","median eminence","cavernous sinus","sphenoid sinus"],"answer":1,"exp":"The primary capillary plexus is at the median eminence. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"The hypophyseal portal vessels carry regulatory hormones from the hypothalamus to the","choices":["posterior pituitary","thyroid gland","adrenal medulla","anterior pituitary"],"answer":3,"exp":"Portal veins carry regulatory hormones to the anterior pituitary. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which artery is most closely associated with the primary capillary plexus supplying the anterior pituitary?","choices":["Posterior communicating artery","Middle cerebral artery","Inferior thyroid artery","Superior hypophyseal artery"],"answer":3,"exp":"The superior hypophyseal artery supplies the portal system. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which artery primarily supplies the posterior pituitary?","choices":["Superior cerebellar artery","Inferior hypophyseal artery","Superior thyroid artery","Anterior spinal artery"],"answer":1,"exp":"The inferior hypophyseal artery mainly supplies the posterior lobe. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which anterior pituitary cell produces growth hormone?","choices":["Corticotrope","Somatotrope","Gonadotrope","Thyrotrope"],"answer":1,"exp":"Somatotropes produce GH. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which anterior pituitary cell produces prolactin?","choices":["Gonadotrope","Thyrotrope","Lactotrope","Corticotrope"],"answer":2,"exp":"Lactotropes produce prolactin. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which cells produce FSH and LH?","choices":["Pituicytes","Somatotropes","Lactotropes","Gonadotropes"],"answer":3,"exp":"Gonadotropes produce FSH and LH. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Which cell produces TSH?","choices":["Chief cell","Somatotrope","Chromaffin cell","Thyrotrope"],"answer":3,"exp":"Thyrotropes produce TSH. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"ACTH is released primarily by","choices":["lactotropes","somatotropes","corticotropes","thyrotropes"],"answer":2,"exp":"Corticotropes release ACTH. — Anatomy Exam 3 — II — Hypothalamus and Pituitary Gland"},{"q":"Chromophobes are characterized by","choices":["no visible cytoplasmic granules","production of calcitonin","storage of colloid","abundant secretory granules"],"answer":0,"exp":"Chromophobes lack visible cytoplasmic granules. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"Acidophils of the anterior pituitary produce","choices":["ADH and oxytocin","TSH and ACTH","FSH and LH only","GH and prolactin"],"answer":3,"exp":"Acidophils produce GH and prolactin. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"Basophils of the anterior pituitary produce all of the following except","choices":["ACTH","GH","TSH","FSH"],"answer":1,"exp":"GH is produced by acidophils, not basophils. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"Which structure is characteristic of the posterior pituitary?","choices":["Pancreatic acini","Thyroid follicles","Adrenal glomeruli","Herring bodies"],"answer":3,"exp":"Herring bodies are found in the posterior pituitary. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"Pituicytes are","choices":["endocrine cells of the anterior pituitary","adrenal cortical cells","supporting glial cells of the posterior pituitary","thyroid follicular cells"],"answer":2,"exp":"Pituicytes are supporting glial cells. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"The hypothalamo-hypophyseal tract consists primarily of","choices":["hypothalamic axons","smooth muscle fibers","lymphatic vessels","venous channels"],"answer":0,"exp":"The hypothalamo-hypophyseal tract consists of hypothalamic axons. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"Herring bodies represent accumulations of","choices":["insulin granules","colloid and thyroglobulin","steroid droplets","stored neurosecretory material"],"answer":3,"exp":"Herring bodies store neurosecretory material. — Anatomy Exam 3 — III — Pituitary Histology"},{"q":"The thyroid gland lies approximately between vertebral levels","choices":["T4-T7","C1-C3","T10-L1","C5-T1"],"answer":3,"exp":"The thyroid extends approximately from C5 to T1. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The thyroid gland is composed primarily of","choices":["two lobes connected by the pyramidal process only","four lobes without an isthmus","two lobes connected by an isthmus","one midline lobe"],"answer":2,"exp":"It has two lobes connected by an isthmus. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The apex of each thyroid lobe lies near the","choices":["sternoclavicular joint","hyoid bone only","sixth tracheal ring","oblique line of the thyroid cartilage"],"answer":3,"exp":"The apex reaches the oblique line of the thyroid cartilage. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The base of each thyroid lobe is located approximately at the level of the","choices":["cricoid cartilage only","first tracheal ring","fourth or fifth tracheal ring","hyoid bone"],"answer":2,"exp":"The base lies near the fourth or fifth tracheal ring. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The thyroid isthmus usually overlies the","choices":["first cervical vertebra","upper esophagus","second and third tracheal rings","sixth and seventh tracheal rings"],"answer":2,"exp":"The isthmus usually overlies the second and third tracheal rings. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"Which muscles cover the thyroid isthmus anteriorly?","choices":["Thyrohyoid and digastric","Sternocleidomastoid and trapezius","Sternohyoid and sternothyroid","Mylohyoid and geniohyoid"],"answer":2,"exp":"Sternohyoid and sternothyroid cover the isthmus. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The thyroid gland moves during swallowing because it is attached to the laryngeal framework through the","choices":["pretracheal fascia","prevertebral fascia","alar fascia","carotid sheath"],"answer":0,"exp":"The pretracheal fascia causes the thyroid to move with swallowing. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The medial surface of the thyroid is related to all of the following except","choices":["esophagus","parotid gland","larynx","trachea"],"answer":1,"exp":"The parotid gland is not a medial thyroid relation. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"Which nerve is closely related to the tracheoesophageal groove and medial thyroid surface?","choices":["Recurrent laryngeal nerve","Hypoglossal nerve","Accessory nerve","Phrenic nerve"],"answer":0,"exp":"The recurrent laryngeal nerve lies near the tracheoesophageal groove. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The external laryngeal nerve is especially related to the","choices":["thyroidea ima artery","superior thyroid artery","middle thyroid vein","inferior thyroid vein"],"answer":1,"exp":"The external laryngeal nerve is closely related to the superior thyroid artery. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The posterior surface of the thyroid is related laterally to the","choices":["submandibular gland","thoracic duct only","carotid sheath","vertebral artery"],"answer":2,"exp":"The posterior thyroid surface is related to the carotid sheath. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"Which structure is normally lateral to the common carotid artery within the carotid sheath?","choices":["Sympathetic trunk","Vagus nerve","Recurrent laryngeal nerve","Internal jugular vein"],"answer":3,"exp":"The internal jugular vein lies lateral to the carotid artery. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The vagus nerve is contained within the","choices":["carotid sheath","retropharyngeal space","thyroid capsule","pretracheal fascia"],"answer":0,"exp":"The vagus nerve is contained in the carotid sheath. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"A pyramidal lobe of the thyroid most commonly arises from the","choices":["inferior thyroid artery","posterior surface of the left lobe","lower border of the right lobe","upper border of the isthmus"],"answer":3,"exp":"The pyramidal lobe commonly arises from the superior isthmus. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The levator glandulae thyroideae may connect the pyramidal lobe to the","choices":["mandible","sternum","clavicle","hyoid bone"],"answer":3,"exp":"The levator glandulae thyroideae may connect to the hyoid bone. — Anatomy Exam 3 — IV — Thyroid Gross Anatomy"},{"q":"The structural unit of the thyroid gland is the","choices":["lobule of Langerhans","zona fasciculata","follicle","acinus"],"answer":2,"exp":"The thyroid follicle is the structural unit of the gland. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"A thyroid follicle is lined primarily by","choices":["transitional epithelium","simple cuboidal epithelium","pseudostratified columnar epithelium","stratified squamous epithelium"],"answer":1,"exp":"Thyroid follicles are lined by simple cuboidal epithelium. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The central material within a thyroid follicle is called","choices":["colloid","cortex","sinusoid","medulla"],"answer":0,"exp":"The central follicular material is colloid. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"Highly active thyroid follicles generally contain","choices":["flatter epithelial cells","no colloid","stratified epithelium","taller epithelial cells"],"answer":3,"exp":"Active follicles have taller epithelial cells. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"Parafollicular cells secrete","choices":["parathyroid hormone","thyroglobulin","TSH","calcitonin"],"answer":3,"exp":"Parafollicular cells secrete calcitonin. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"Parafollicular cells are also called","choices":["chief cells","oxyphil cells","C cells","chromaffin cells"],"answer":2,"exp":"Parafollicular cells are also called C cells. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The superior thyroid artery usually arises from the","choices":["external carotid artery","aortic arch","subclavian artery","common carotid artery"],"answer":0,"exp":"The superior thyroid artery arises from the external carotid artery. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The inferior thyroid artery usually arises from the","choices":["internal thoracic artery","common carotid artery","thyrocervical trunk","external carotid artery"],"answer":2,"exp":"The inferior thyroid artery arises from the thyrocervical trunk. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The thyrocervical trunk is a branch of the","choices":["subclavian artery","descending thoracic aorta","external carotid artery","brachiocephalic vein"],"answer":0,"exp":"The thyrocervical trunk comes from the subclavian artery. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The inferior thyroid artery is closely related to the","choices":["hypoglossal nerve only","optic nerve","recurrent laryngeal nerve","facial nerve"],"answer":2,"exp":"The inferior thyroid artery is related to the recurrent laryngeal nerve. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The thyroidea ima artery is","choices":["the main supply to the thyroid lobes","always present","a branch of the internal carotid artery","an uncommon arterial variant"],"answer":3,"exp":"The thyroidea ima is an uncommon variant. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The thyroidea ima artery may arise from the","choices":["axillary artery","brachiocephalic artery or aortic arch","external carotid artery only","vertebral artery"],"answer":1,"exp":"It may arise from the brachiocephalic artery or aortic arch. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The superior and middle thyroid veins usually drain into the","choices":["internal jugular vein","azygos vein","external jugular vein","subclavian artery"],"answer":0,"exp":"Superior and middle thyroid veins drain to the internal jugular vein. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The inferior thyroid veins usually drain into the","choices":["facial vein","brachiocephalic veins","internal carotid artery","superior sagittal sinus"],"answer":1,"exp":"Inferior thyroid veins drain to the brachiocephalic veins. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"Thyroid lymphatic drainage includes the","choices":["inguinal nodes","paratracheal and deep cervical nodes","popliteal nodes","axillary nodes only"],"answer":1,"exp":"Thyroid lymph drains to paratracheal and deep cervical nodes. — Anatomy Exam 3 — V — Thyroid Histology and Vascular Anatomy"},{"q":"The parathyroid glands are usually located","choices":["inside the pituitary fossa","along the posterior thyroid surface","on the anterior thyroid surface","within the adrenal medulla"],"answer":1,"exp":"Parathyroids lie on the posterior thyroid surface. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The usual number of parathyroid glands is","choices":["six","three","two","four"],"answer":3,"exp":"Four glands are most common. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The superior parathyroid glands are generally","choices":["located in the mediastinum","more constant in location","more variable in location","always inside the thyroid"],"answer":1,"exp":"Superior parathyroids are more constant in position. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The inferior parathyroid glands may be found","choices":["within the pituitary gland","only at the upper thyroid pole","above or below the inferior thyroid arteries","only inside the carotid artery"],"answer":2,"exp":"Inferior glands may lie above or below the inferior thyroid arteries. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The primary hormone-secreting cells of the parathyroid are the","choices":["somatotropes","follicular cells","principal or chief cells","chromaffin cells"],"answer":2,"exp":"Chief cells are the main hormone-producing cells. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"Chief cells produce","choices":["insulin","PTH","cortisol","calcitonin"],"answer":1,"exp":"Chief cells produce PTH. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"Oxyphil cells are described as","choices":["larger and strongly eosinophilic","modified neurons","filled with colloid","small and basophilic"],"answer":0,"exp":"Oxyphil cells are larger and eosinophilic. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"Which finding commonly increases in the parathyroid gland with age?","choices":["Adipose tissue","Skeletal muscle","Colloid","Cartilage"],"answer":0,"exp":"Adipose tissue increases with age. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The parathyroid glands are closely related to the","choices":["splenic hilum","tracheoesophageal groove","optic chiasm","sphenoid sinus"],"answer":1,"exp":"Parathyroids lie near the tracheoesophageal groove. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The parathyroid glands generally share their vascular, lymphatic, and nerve supply with the","choices":["adrenal gland","pituitary gland","thyroid gland","pancreas"],"answer":2,"exp":"Their vascular, nerve, and lymph supply generally follows the thyroid. — Anatomy Exam 3 — VI — Parathyroid Glands"},{"q":"The pancreas lies primarily in the","choices":["epigastric and left hypochondriac regions","pelvic cavity","right hypochondriac region only","hypogastric and right iliac regions"],"answer":0,"exp":"The pancreas lies mainly in the epigastric and left hypochondriac regions. — Anatomy Exam 3 — VII — Pancreas"},{"q":"Most of the pancreas is","choices":["intraperitoneal","retroperitoneal","contained in the mesocolon","within the lesser omentum"],"answer":1,"exp":"Most of the pancreas is retroperitoneal. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The head of the pancreas lies within the","choices":["splenic hilum","renal pelvis","concavity of the duodenum","liver fissure"],"answer":2,"exp":"The head lies in the duodenal concavity. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The tail of the pancreas extends toward the","choices":["right kidney","spleen","cecum","gallbladder"],"answer":1,"exp":"The tail extends toward the spleen. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The body of the pancreas crosses anterior to the","choices":["uterus","urinary bladder","right atrium","left kidney"],"answer":3,"exp":"The body crosses anterior to the left kidney. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The pancreas is related anteriorly to the","choices":["transverse colon","aorta only","inferior vena cava only","vertebral canal"],"answer":0,"exp":"The transverse colon is anteriorly related. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The aorta and inferior vena cava lie primarily","choices":["within the pancreatic duct","posterior to the pancreas","anterior to the pancreas","lateral to the tail only"],"answer":1,"exp":"The aorta and IVC lie posterior to the pancreas. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The uncinate process lies","choices":["anterior to the SMA and SMV","posterior to the SMA and SMV","inside the spleen","within the lesser omentum"],"answer":1,"exp":"The uncinate process lies posterior to the SMA and SMV. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The uncinate process lies anterior to the","choices":["liver","stomach","aorta","transverse colon"],"answer":2,"exp":"It lies anterior to the aorta. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The neck of the pancreas lies anterior to the","choices":["SMV","IVC only","splenic artery only","left ureter"],"answer":0,"exp":"The pancreatic neck lies anterior to the SMV. — Anatomy Exam 3 — VII — Pancreas"},{"q":"Which vessel runs along the superior border of the pancreatic body and tail?","choices":["Cystic artery","Inferior mesenteric artery","Splenic artery","Renal artery"],"answer":2,"exp":"The splenic artery travels along the superior border. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The splenic vein lies primarily","choices":["on the anterior surface of the pancreas","within the common bile duct","on the posterior surface of the pancreas","inside the pancreatic duct"],"answer":2,"exp":"The splenic vein lies on the posterior pancreatic surface. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The splenic vein ultimately contributes to formation of the","choices":["azygos vein","portal vein","external iliac vein","inferior vena cava"],"answer":1,"exp":"The splenic vein helps form the portal vein. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The common bile duct passes through or behind the","choices":["head of the pancreas","tail of the pancreas","adrenal cortex","splenic hilum"],"answer":0,"exp":"The common bile duct passes behind or through the pancreatic head. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The common bile duct and main pancreatic duct commonly unite at the","choices":["cystic duct","pyloric canal","hepatopancreatic ampulla","minor papilla"],"answer":2,"exp":"It joins the main pancreatic duct at the hepatopancreatic ampulla. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The hepatopancreatic ampulla is also called the ampulla of","choices":["Vater","Treitz","Santorini","Wirsung"],"answer":0,"exp":"The hepatopancreatic ampulla is the ampulla of Vater. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The main pancreatic duct is the duct of","choices":["Vater","Wirsung","Oddi","Santorini"],"answer":1,"exp":"Main pancreatic duct = duct of Wirsung. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The accessory pancreatic duct is the duct of","choices":["Vater","Santorini","Treitz","Wirsung"],"answer":1,"exp":"Accessory pancreatic duct = duct of Santorini. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The accessory pancreatic duct opens into the duodenum at the","choices":["pyloric sphincter","minor papilla","ileocecal valve","major papilla"],"answer":1,"exp":"Santorini opens at the minor duodenal papilla. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The main pancreatic duct usually opens through the","choices":["major duodenal papilla","ileal papilla","minor duodenal papilla","gastric cardia"],"answer":0,"exp":"Wirsung usually opens at the major duodenal papilla. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The head of the pancreas is supplied primarily by","choices":["cystic artery","inferior mesenteric artery","superior and inferior pancreaticoduodenal arteries","left gastric artery only"],"answer":2,"exp":"The head receives superior and inferior pancreaticoduodenal arteries. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The superior pancreaticoduodenal arteries arise from the","choices":["inferior mesenteric artery","splenic artery only","gastroduodenal artery","renal artery"],"answer":2,"exp":"Superior pancreaticoduodenal branches come from the gastroduodenal artery. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The inferior pancreaticoduodenal arteries arise from the","choices":["inferior mesenteric artery","celiac trunk directly","superior mesenteric artery","common iliac artery"],"answer":2,"exp":"Inferior pancreaticoduodenal branches come from the SMA. — Anatomy Exam 3 — VII — Pancreas"},{"q":"The body and tail of the pancreas receive arterial supply primarily from branches of the","choices":["inferior mesenteric artery","middle suprarenal artery","cystic artery","splenic artery"],"answer":3,"exp":"The body and tail receive branches from the splenic artery. — Anatomy Exam 3 — VII — Pancreas"},{"q":"Pancreatic carcinoma occurs most commonly in the","choices":["accessory duct only","body only","tail","head"],"answer":3,"exp":"Pancreatic carcinoma commonly occurs in the head. — Anatomy Exam 3 — VII — Pancreas"},{"q":"A tumor in the pancreatic head may obstruct the","choices":["renal artery","ureter","common bile duct","inferior mesenteric vein"],"answer":2,"exp":"A pancreatic head tumor can obstruct the common bile duct. — Anatomy Exam 3 — VII — Pancreas"},{"q":"Most pancreatic tissue is composed of","choices":["thyroid follicles","adrenal cortex","exocrine acini","pituitary chromophobes"],"answer":2,"exp":"Most pancreatic tissue consists of exocrine acini. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"The endocrine portion of the pancreas is formed by the","choices":["acini of Wirsung","islets of Langerhans","glomeruli of Vater","follicles of Santorini"],"answer":1,"exp":"The endocrine tissue is organized into islets of Langerhans. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"Beta cells produce","choices":["glucagon","pancreatic polypeptide","insulin","somatostatin"],"answer":2,"exp":"Beta cells produce insulin. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"Alpha cells produce","choices":["calcitonin","aldosterone","glucagon","insulin"],"answer":2,"exp":"Alpha cells produce glucagon. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"Delta cells produce","choices":["cortisol","thyroxine","somatostatin","prolactin"],"answer":2,"exp":"Delta cells produce somatostatin. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"F cells produce","choices":["growth hormone","calcitriol","pancreatic polypeptide","epinephrine"],"answer":2,"exp":"F cells produce pancreatic polypeptide. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"Pancreatic islets are highly vascularized and contain","choices":["lymphatic sinusoids only","continuous capillaries only","no capillaries","fenestrated capillaries"],"answer":3,"exp":"Endocrine islets contain fenestrated capillaries. — Anatomy Exam 3 — VIII — Pancreatic Histology"},{"q":"The adrenal glands are also called","choices":["suprarenal glands","pararenal glands","pineal glands","hypophyseal glands"],"answer":0,"exp":"Adrenal glands are also called suprarenal glands. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The adrenal glands lie","choices":["inside the renal pelvis","inferior to the kidneys","anterior to the bladder","on the superior poles of the kidneys"],"answer":3,"exp":"They sit on the superior poles of the kidneys. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The right adrenal gland is typically","choices":["bilobed","pyramidal","spherical","semilunar"],"answer":1,"exp":"The right adrenal gland is pyramidal. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The left adrenal gland is typically","choices":["cuboidal","pyramidal","triangular only","semilunar"],"answer":3,"exp":"The left adrenal gland is semilunar. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The right adrenal gland is related anteriorly to the","choices":["descending colon only","spleen and jejunum","liver and IVC","stomach and pancreas"],"answer":2,"exp":"The right gland is anteriorly related to the liver and IVC. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The left adrenal gland is related anteriorly to the","choices":["duodenum and gallbladder","stomach and pancreas","liver and IVC","cecum and appendix"],"answer":1,"exp":"The left gland is anteriorly related to the stomach and pancreas. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"Both adrenal glands are related posteriorly to the","choices":["liver only","pancreas","stomach","diaphragm"],"answer":3,"exp":"Both are posteriorly related to the diaphragm. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The inferior relation of each adrenal gland is the","choices":["spleen","thyroid gland","kidney","duodenum"],"answer":2,"exp":"Each adrenal gland rests superior to a kidney. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The superior suprarenal arteries arise from the","choices":["renal arteries","celiac trunk","abdominal aorta directly","inferior phrenic arteries"],"answer":3,"exp":"Superior suprarenal arteries arise from inferior phrenic arteries. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The middle suprarenal arteries arise directly from the","choices":["inferior phrenic arteries","superior mesenteric artery","abdominal aorta","renal arteries"],"answer":2,"exp":"Middle suprarenal arteries arise directly from the aorta. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The inferior suprarenal arteries arise from the","choices":["renal arteries","common hepatic artery","splenic artery","inferior mesenteric artery"],"answer":0,"exp":"Inferior suprarenal arteries arise from renal arteries. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The right suprarenal vein drains directly into the","choices":["splenic vein","left renal vein","inferior vena cava","portal vein"],"answer":2,"exp":"The right suprarenal vein drains directly to the IVC. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The left suprarenal vein drains primarily into the","choices":["left renal vein","azygos vein","portal vein","inferior vena cava directly"],"answer":0,"exp":"The left suprarenal vein drains to the left renal vein. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"Which adrenal gland generally has a shorter vein?","choices":["Neither has a vein","Right","Both are equal","Left"],"answer":1,"exp":"The right suprarenal vein is shorter. — Anatomy Exam 3 — IX — Adrenal Glands"},{"q":"The adrenal gland is divided into","choices":["cortex and medulla","follicles and colloid","anterior and posterior lobes","acini and islets"],"answer":0,"exp":"The gland has cortex and medulla. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The outermost adrenal cortical zone is the","choices":["zona glomerulosa","zona fasciculata","medulla","zona reticularis"],"answer":0,"exp":"Zona glomerulosa is the outermost cortical layer. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The middle adrenal cortical zone is the","choices":["zona fasciculata","zona glomerulosa","pars distalis","zona reticularis"],"answer":0,"exp":"Zona fasciculata is the middle cortical layer. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The innermost cortical zone is the","choices":["zona reticularis","zona fasciculata","medulla","zona glomerulosa"],"answer":0,"exp":"Zona reticularis is the innermost cortical layer. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The zona glomerulosa produces primarily","choices":["thyroid hormones","mineralocorticoids","catecholamines","glucocorticoids"],"answer":1,"exp":"Zona glomerulosa produces mineralocorticoids. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The zona fasciculata produces primarily","choices":["epinephrine","calcitonin","cortisol","aldosterone"],"answer":2,"exp":"Zona fasciculata produces cortisol. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The zona reticularis produces primarily","choices":["androgens","catecholamines","insulin","PTH"],"answer":0,"exp":"Zona reticularis produces androgens. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"Cells of the zona fasciculata are arranged mainly in","choices":["radial columns","spherical follicles","isolated islets","nerve bundles"],"answer":0,"exp":"Fasciculata cells form radial columns. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The principal cells of the adrenal medulla are","choices":["follicular cells","pituicytes","chief cells","chromaffin cells"],"answer":3,"exp":"Chromaffin cells are the main adrenal medullary cells. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"Chromaffin cells are functionally comparable to modified","choices":["postganglionic sympathetic neurons","sensory neurons","somatic motor neurons","preganglionic parasympathetic neurons"],"answer":0,"exp":"Chromaffin cells resemble modified postganglionic sympathetic neurons. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"The adrenal medulla secretes primarily","choices":["epinephrine and norepinephrine","TSH and ACTH","insulin and glucagon","aldosterone and cortisol"],"answer":0,"exp":"The medulla secretes epinephrine and norepinephrine. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"A prominent histologic feature of the adrenal medulla is a","choices":["central vein","pancreatic duct","portal triad","central colloid-filled follicle"],"answer":0,"exp":"A large central vein is characteristic of the medulla. — Anatomy Exam 3 — X — Adrenal Histology"},{"q":"Which endocrine organ contains follicles filled with colloid?","choices":["Adrenal","Pituitary","Parathyroid","Thyroid"],"answer":3,"exp":"The thyroid contains colloid-filled follicles. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which endocrine organ contains chief and oxyphil cells?","choices":["Parathyroid","Thyroid","Pancreas","Pituitary"],"answer":0,"exp":"Parathyroids contain chief and oxyphil cells. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which organ contains both endocrine islets and exocrine acini?","choices":["Thyroid gland","Adrenal gland","Pancreas","Pituitary"],"answer":2,"exp":"The pancreas has endocrine islets and exocrine acini. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which gland contains acidophils, basophils, and chromophobes?","choices":["Thyroid","Adrenal cortex","Parathyroid","Anterior pituitary"],"answer":3,"exp":"The anterior pituitary contains acidophils, basophils, and chromophobes. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which gland contains pituicytes and Herring bodies?","choices":["Neurohypophysis","Thyroid","Adenohypophysis","Parathyroid"],"answer":0,"exp":"The neurohypophysis contains pituicytes and Herring bodies. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which endocrine organ lies within the sella turcica?","choices":["Adrenal gland","Pituitary gland","Pineal gland","Thyroid gland"],"answer":1,"exp":"The pituitary lies in the sella turcica. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"Which endocrine organs are located on the posterior aspect of another endocrine gland?","choices":["Parathyroid glands","Adrenal glands","Pituitary lobes","Pancreatic islets"],"answer":0,"exp":"Parathyroids sit on the posterior surface of the thyroid. — Anatomy Exam 3 — XI — Compare and Contrast"},{"q":"During ligation of the superior thyroid artery, which nerve is most at risk?","choices":["External laryngeal nerve","Hypoglossal nerve","Recurrent laryngeal nerve","Phrenic nerve"],"answer":0,"exp":"The external laryngeal nerve is at risk near the superior thyroid artery. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"During ligation of the inferior thyroid artery, which nerve is especially at risk?","choices":["Glossopharyngeal nerve","Facial nerve","Recurrent laryngeal nerve","External laryngeal nerve"],"answer":2,"exp":"The recurrent laryngeal nerve is at risk near the inferior thyroid artery. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A patient develops hoarseness after thyroid surgery. Injury to which nerve is most likely?","choices":["Phrenic nerve","Greater auricular nerve","Optic nerve","Recurrent laryngeal nerve"],"answer":3,"exp":"Recurrent laryngeal nerve damage commonly causes hoarseness. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A mass in the head of the pancreas causes jaundice because it compresses the","choices":["splenic artery","left renal vein","inferior vena cava","common bile duct"],"answer":3,"exp":"Pancreatic head tumors may compress the common bile duct. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A surgeon removing the right adrenal gland must be especially careful because its short vein drains directly into the","choices":["portal vein","inferior vena cava","splenic vein","left renal vein"],"answer":1,"exp":"The right suprarenal vein drains directly to the IVC. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A lesion of the posterior pituitary may impair release of","choices":["TSH","GH","ACTH","ADH"],"answer":3,"exp":"The posterior pituitary releases ADH. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A pituitary tumor extending inferiorly could enter the","choices":["sphenoid sinus","maxillary sinus","frontal sinus","mastoid air cells"],"answer":0,"exp":"Inferior growth may enter the sphenoid sinus. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A lesion involving the cavernous sinus adjacent to the pituitary could affect the","choices":["internal carotid artery and multiple cranial nerves","optic nerve only","vertebral artery only","facial artery and vein"],"answer":0,"exp":"The cavernous sinus contains the internal carotid artery and several cranial nerves. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"Accidental removal of all parathyroid tissue during thyroidectomy would most directly affect secretion of","choices":["ACTH","PTH","calcitonin","TSH"],"answer":1,"exp":"Parathyroid removal reduces PTH secretion. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"},{"q":"A histology slide shows pale-staining clusters surrounded by darker pancreatic acini. The pale clusters are most likely","choices":["pituitary basophils","adrenal cortical zones","pancreatic islets","thyroid follicles"],"answer":2,"exp":"Pale clusters among darker acini are pancreatic islets. — Anatomy Exam 3 — XII — Clinical and Anatomical Application"}]};
